const SUBSCRIPTION_CONFIRMATION: &str = r#"{"jsonrpc":"2.0","result":10397413,"id":1}"#;

#[test]
fn extracts_the_single_real_event_from_a_plain_trade_notification() {
    let extracted = extract_events(REAL_NOTIFICATION_1).expect("should parse as a logsNotification");
    assert_eq!(extracted.skipped_malformed, 0);
    assert_eq!(extracted.events.len(), 1);
    assert_eq!(
        extracted.events[0].signature,
        "2SXAxsRfoXto8ayGbuAgENNtzex3sP4UmFE67fj6WDGWhoDbt81RXVG5a1VodztfCx9ukHFxmJX6Q38iUUdKgzcY"
    );
    assert_eq!(extracted.events[0].log_index, 0);

    match decode_event(&extracted.events[0].data).expect("should decode as a known Pump event") {
        PumpEvent::Trade(t) => assert!(t.is_buy),
        other => panic!("expected Trade, got {other:?}"),
    }
}

#[test]
fn extracts_all_three_program_data_lines_but_only_one_decodes_as_pump() {
    let extracted = extract_events(REAL_NOTIFICATION_2).expect("should parse as a logsNotification");
    assert_eq!(extracted.skipped_malformed, 0);
    let events = extracted.events;
    assert_eq!(events.len(), 3);
    assert_eq!(events[0].log_index, 0);
    assert_eq!(events[1].log_index, 1);
    assert_eq!(events[2].log_index, 2);
    // All three share the one transaction's signature.
    let sig = &events[0].signature;
    assert!(events.iter().all(|e| &e.signature == sig));

    let decoded: Vec<Option<PumpEvent>> = events.iter().map(|e| decode_event(&e.data)).collect();
    assert!(decoded[0].is_none());
    assert!(decoded[1].is_none());
    match decoded[2].as_ref().expect("third line should decode") {
        PumpEvent::Trade(_) => {}
        other => panic!("expected Trade, got {other:?}"),
    }
}

#[test]
fn the_subscription_confirmation_message_is_not_a_notification() {
    assert_eq!(extract_events(SUBSCRIPTION_CONFIRMATION), None);
}

#[test]
fn garbage_input_is_not_a_notification() {
    assert_eq!(extract_events("not json at all"), None);
    assert_eq!(extract_events("{}"), None);
}

#[test]
fn a_malformed_program_data_line_is_counted_not_silently_dropped() {
    // Same shape as REAL_NOTIFICATION_1 but with the base64 payload
    // truncated mid-string (as Solana does when it truncates an
    // oversized `logs` array) — must be counted, not vanish with zero
    // trace.
    let notification = r#"{"jsonrpc": "2.0", "method": "logsNotification", "params": {"result": {"context": {"slot": 1}, "value": {"signature": "sig1", "err": null, "logs": ["Program data: not-valid-base64!!!", "Program data: vdt/007mYe4="]}}, "subscription": 1}}"#;
    let extracted = extract_events(notification).expect("should parse as a logsNotification");
    assert_eq!(extracted.skipped_malformed, 1);
    assert_eq!(extracted.events.len(), 1);
    assert_eq!(extracted.events[0].log_index, 0);
}

#[test]
fn a_failed_transaction_yields_no_events_but_still_parses() {
    let notification = r#"{"jsonrpc": "2.0", "method": "logsNotification", "params": {"result": {"context": {"slot": 1}, "value": {"signature": "sig1", "err": {"InstructionError": [0, "Custom"]}, "logs": ["Program data: vdt/007mYe4="]}}, "subscription": 1}}"#;
    let extracted = extract_events(notification).expect("should parse as a logsNotification");
    assert_eq!(extracted.events.len(), 0);
    assert_eq!(extracted.skipped_malformed, 0);
}
